import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';
import { INITIAL_EMAILS, INITIAL_SHADOWCHAT_FEED } from '../data/commsData';
import { Plus, Smile, Mail, Briefcase, Users, MessageSquare, ArrowLeft, GraduationCap } from 'lucide-react';

export default function CommsApp() {
  const [activeTab, setActiveTab] = useState('comms'); // 'messages' (Personal) | 'comms' (Work/School)
  const [activeContact, setActiveContact] = useState('Aelita');
  const [selectedMail, setSelectedMail] = useState(null);
  const [composing, setComposing] = useState(false);
  const [composeRecipient, setComposeRecipient] = useState('Aelita');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');

  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);
  const advanceStarterPhase = useOSStore((s) => s.advanceStarterPhase);

  // Initial Data
  const [emails, setEmails] = useState(INITIAL_EMAILS);
  const [chatFeed, setChatFeed] = useState(INITIAL_SHADOWCHAT_FEED);
  const [chatInput, setChatInput] = useState('');

  // Contacts lists
  const personalContacts = ['Aelita', 'Odd', 'Yumi', 'Jeremie', 'Ulrich', 'Sissi', 'Nerya'];
  const workSchoolContacts = ['Dean Cassian Rook', 'Dr. Maelis Voss', 'Prof. Corvin Vale', 'Agent Mara Quell', 'Faith Medical'];

  const activeContactsList = activeTab === 'messages' ? personalContacts : workSchoolContacts;

  const claimAttachment = (mailId) => {
    setEmails((prev) =>
      prev.map((m) => {
        if (m.id === mailId && m.attachment && !m.attachment.claimed) {
          addCredits(m.attachment.amount);
          addXP(m.attachment.amount / 2);
          advanceStarterPhase();
          useOSStore.getState().addSkillXP('Communication', 25);
          useOSStore.getState().addSkillXP('Networking', 25);
          const updatedMail = { ...m, attachment: { ...m.attachment, claimed: true } };
          setSelectedMail(updatedMail);
          return updatedMail;
        }
        return m;
      })
    );
  };

  const handleSendChat = (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && chatInput.trim()) {
      setChatFeed((prev) => [
        ...prev,
        { id: Date.now(), user: 'You (Operative)', team: activeContact, text: chatInput.trim(), time: 'Just now' },
      ]);
      setChatInput('');
      useOSStore.getState().addSkillXP('Communication', 10);
    }
  };

  const handleSendCompose = () => {
    if (!composeSubject.trim() || !composeBody.trim()) return;
    setEmails((prev) => [
      {
        id: `SENT-${Date.now().toString().slice(-4)}`,
        sender: `To: ${composeRecipient}`,
        faction: 'Sent Transmission',
        subject: composeSubject,
        time: 'Just now',
        read: true,
        attachment: null,
        body: composeBody,
      },
      ...prev,
    ]);
    setComposing(false);
    setComposeSubject('');
    setComposeBody('');
  };

  const unreadEmailCount = emails.filter((e) => !e.read && !e.id.startsWith('SENT')).length;

  return (
    <div className="flex h-full w-full bg-[#B8B2C4] text-slate-900 font-sans text-xs select-none border-4 border-slate-950 overflow-hidden shadow-2xl">
      {/* ------------------------------------------------------------------ */}
      {/* LEFT SIDEBAR PANEL (CONTACT STACK + BOTTOM MESH ACTION ICONS)      */}
      {/* ------------------------------------------------------------------ */}
      <div className="w-56 bg-[#C8C2D4] border-r-4 border-slate-950 p-3 flex flex-col justify-between shrink-0">
        {/* Top Header Boxes matching wireframe */}
        <div className="space-y-2">
          <div className="bg-[#B0A7BF] border-2 border-slate-950 p-2 font-mono font-black text-[11px] text-purple-950 uppercase tracking-wider flex items-center justify-between shadow-sm">
            <span>{activeTab === 'messages' ? '💬 Personal Messages' : '🎓 Comms (Work/School)'}</span>
          </div>

          {/* Middle Channel Stack */}
          <div className="space-y-1.5 overflow-y-auto max-h-[280px] pr-1 pt-1">
            {activeContactsList.map((contact) => (
              <button
                key={contact}
                onClick={() => setActiveContact(contact)}
                className={`w-full py-2 px-3 rounded-lg border-2 border-slate-950 text-left font-mono font-bold text-xs transition shadow-sm ${
                  activeContact === contact
                    ? 'bg-[#E5E0EE] text-purple-950 border-purple-900 font-extrabold translate-x-1'
                    : 'bg-[#B0A7BF] text-slate-900 hover:bg-[#D4CEE0]'
                }`}
              >
                {contact}
              </button>
            ))}
          </div>
        </div>

        {/* Bottom Action Bar: Side-by-Side Icons matching wireframe */}
        {/* Left Icon (Mail Envelope ✉️): Personal Messages */}
        {/* Right Icon (Backpack 🎒): Comms (Work/School) */}
        <div className="flex items-center justify-around pt-3 border-t-4 border-slate-950 bg-[#B8B2C4] -mx-3 -mb-3 p-3">
          <button
            onClick={() => {
              setActiveTab('messages');
              setActiveContact('Aelita');
            }}
            className={`p-2.5 rounded-xl border-2 border-slate-950 transition shadow-md relative ${
              activeTab === 'messages'
                ? 'bg-purple-600 text-white ring-2 ring-purple-900'
                : 'bg-[#D4CEE0] text-purple-950 hover:bg-purple-300'
            }`}
            title="Personal Messages (DMs & Social)"
          >
            <Mail size={22} />
            {unreadEmailCount > 0 && (
              <span className="absolute -top-1 -right-1 bg-red-500 text-white font-bold text-[9px] h-4 w-4 rounded-full flex items-center justify-center border border-slate-950 shadow">
                {unreadEmailCount}
              </span>
            )}
          </button>

          <button
            onClick={() => {
              setActiveTab('comms');
              setActiveContact('Dean Cassian Rook');
            }}
            className={`p-2.5 rounded-xl border-2 border-slate-950 transition shadow-md ${
              activeTab === 'comms'
                ? 'bg-purple-600 text-white ring-2 ring-purple-900'
                : 'bg-[#D4CEE0] text-purple-950 hover:bg-purple-300'
            }`}
            title="Comms (Work & School Transmissions)"
          >
            <span className="text-xl">🎒</span>
          </button>
        </div>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* RIGHT MAIN CHAT PANEL (MATCHING WIREFRAME: BOLD UNDERLINED COMMS)   */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex-1 flex flex-col justify-between bg-[#B8B2C4] p-4 relative overflow-hidden">
        {/* Inset Light Grey Chat Card Container */}
        <div className="flex-1 flex flex-col justify-between bg-[#DCD8E4] rounded-2xl border-4 border-slate-950 p-4 shadow-inner space-y-3 overflow-hidden">
          {/* Header matching wireframe: Left-aligned bold purple COMMS title with solid underline */}
          <div className="border-b-4 border-slate-950 pb-2">
            <h1 className="font-serif-y2k text-2xl font-black text-purple-950 tracking-widest uppercase">
              COMMS
            </h1>
          </div>

          {/* Active Conversation Feed */}
          <div className="flex-1 overflow-y-auto space-y-3 bg-[#EAE6F2] rounded-xl p-3 border-2 border-slate-950 shadow-inner">
            <div className="flex items-center justify-between border-b border-slate-400 pb-1 font-mono text-[10px] font-bold text-purple-950">
              <span>Channel: {activeContact}</span>
              <span className="text-slate-600">
                {activeTab === 'messages' ? 'Personal DM' : 'Cyacademy Work/School'}
              </span>
            </div>

            {chatFeed.map((msg) => (
              <div
                key={msg.id}
                className={`p-3 rounded-xl border-2 border-slate-950 shadow-sm max-w-[85%] ${
                  msg.user.startsWith('You')
                    ? 'bg-purple-200 text-purple-950 ml-auto'
                    : 'bg-white text-slate-900 mr-auto'
                }`}
              >
                <div className="flex justify-between items-center text-[10px] font-mono font-bold mb-1 border-b border-slate-300 pb-0.5">
                  <span>{msg.user}</span>
                  <span className="opacity-60">{msg.time}</span>
                </div>
                <div className="text-xs font-sans font-medium">{msg.text}</div>
              </div>
            ))}
          </div>

          {/* ------------------------------------------------------------------ */}
          {/* BOTTOM INPUT BAR (MATCHING WIREFRAME: + INPUT 🙂)                  */}
          {/* ------------------------------------------------------------------ */}
          <div className="h-12 bg-white rounded-xl border-2 border-slate-950 flex items-center px-3 gap-2 shadow-md shrink-0">
            <button
              onClick={() => alert('📎 Attachment menu opened!')}
              className="p-1.5 rounded-lg bg-slate-200 hover:bg-slate-300 text-slate-950 font-bold border border-slate-600"
              title="Add Attachment"
            >
              <Plus size={18} />
            </button>

            <input
              type="text"
              value={chatInput}
              onChange={(e) => setChatInput(e.target.value)}
              onKeyDown={handleSendChat}
              placeholder={`Send message to ${activeContact}...`}
              className="flex-1 bg-transparent text-xs text-slate-950 outline-none font-sans font-semibold placeholder-slate-500"
            />

            <button
              onClick={handleSendChat}
              className="p-1.5 rounded-lg bg-purple-300 hover:bg-purple-400 text-purple-950 font-bold border border-slate-950 transition"
              title="Send Message"
            >
              <Smile size={18} />
            </button>
          </div>
        </div>
      </div>

      {/* COMPOSE MODAL */}
      {composing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-96 rounded-2xl border-4 border-slate-950 bg-[#C8C2D4] p-4 text-slate-900 space-y-3 shadow-2xl">
            <div className="flex justify-between border-b-2 border-slate-950 pb-2 font-mono font-bold">
              <span>Compose Transmission</span>
              <button onClick={() => setComposing(false)} className="hover:text-red-700">✕</button>
            </div>

            <div className="space-y-2 text-xs">
              <div>
                <label className="text-[10px] block font-mono font-bold">Recipient:</label>
                <select
                  value={composeRecipient}
                  onChange={(e) => setComposeRecipient(e.target.value)}
                  className="w-full rounded-lg border-2 border-slate-950 bg-white text-slate-900 p-1.5 outline-none font-bold"
                >
                  {activeContactsList.map((c) => (
                    <option key={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-[10px] block font-mono font-bold">Subject:</label>
                <input
                  type="text"
                  value={composeSubject}
                  onChange={(e) => setComposeSubject(e.target.value)}
                  placeholder="Subject line..."
                  className="w-full rounded-lg border-2 border-slate-950 bg-white text-slate-900 p-1.5 outline-none font-bold"
                />
              </div>

              <div>
                <label className="text-[10px] block font-mono font-bold">Message:</label>
                <textarea
                  rows={4}
                  value={composeBody}
                  onChange={(e) => setComposeBody(e.target.value)}
                  placeholder="Write message..."
                  className="w-full rounded-lg border-2 border-slate-950 bg-white text-slate-900 p-1.5 outline-none font-medium resize-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-1">
              <button
                onClick={() => setComposing(false)}
                className="px-3 py-1.5 rounded-lg border-2 border-slate-950 bg-slate-300 text-slate-900 font-bold hover:bg-slate-400"
              >
                Cancel
              </button>
              <button
                onClick={handleSendCompose}
                className="px-4 py-1.5 rounded-lg border-2 border-slate-950 bg-purple-400 text-purple-950 font-bold hover:bg-purple-500"
              >
                Send
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
